-- Additive community API. Existing competition rules and private documents are unchanged.
begin;
create table public.social_settings(owner_id uuid primary key references public.profiles(id) on delete cascade, timezone text not null default 'Europe/Paris');
create table public.friend_pairs(a uuid references public.profiles(id),b uuid references public.profiles(id),sender uuid not null references public.profiles(id),state text not null check(state in ('pending','accepted','declined','cancelled')),updated_at timestamptz not null default now(),created_at timestamptz not null default now(),primary key(a,b),check(a<b),check(sender in (a,b)));
create table public.social_blocks(owner_id uuid references public.profiles(id),target_id uuid references public.profiles(id),primary key(owner_id,target_id),check(owner_id<>target_id));
create table public.social_request_log(owner_id uuid references public.profiles(id),kind text not null,created_at timestamptz not null default now());
create index social_request_rate on public.social_request_log(owner_id,kind,created_at);
create function public.social_uid() returns uuid language plpgsql stable set search_path=public,pg_temp as $$begin if auth.uid() is null then raise exception 'AUTH_REQUIRED';end if;return auth.uid();end$$;
create function public.social_friends(x uuid,y uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$select exists(select 1 from friend_pairs where a=least(x,y) and b=greatest(x,y) and state='accepted') and not exists(select 1 from social_blocks where (owner_id=x and target_id=y) or(owner_id=y and target_id=x))$$;
create function public.friend_action(p_target uuid,p_action text) returns text language plpgsql security definer set search_path=public,pg_temp as $$
declare u uuid:=public.social_uid();r public.friend_pairs%rowtype;begin
 if p_target=u or not exists(select 1 from profiles where id=p_target) then raise exception 'PROFILE_UNAVAILABLE';end if;
 perform pg_advisory_xact_lock(hashtextextended(least(u,p_target)::text||greatest(u,p_target)::text,105));
 select * into r from friend_pairs where a=least(u,p_target) and b=greatest(u,p_target) for update;
 if p_action='block' then
 insert into social_blocks values(u,p_target) on conflict do nothing;
 update friend_pairs set state='cancelled',updated_at=now() where a=least(u,p_target) and b=greatest(u,p_target);
 return 'blocked';end if;
 if exists(select 1 from social_blocks where (owner_id=u and target_id=p_target) or(owner_id=p_target and target_id=u))then raise exception 'PROFILE_UNAVAILABLE';end if;
 if p_action='request' then
 if r.state='accepted' then return 'accepted';end if;
 if r.state='pending' then return case when r.sender=u then 'outgoing' else 'incoming' end;end if;
 if r.state='declined' and r.sender=u and r.updated_at>now()-interval '7 days' then raise exception 'REQUEST_COOLDOWN';end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text,105));
 if (select count(*) from social_request_log where owner_id=u and kind='friend' and created_at>now()-interval '1 day')>=20 then raise exception 'REQUEST_LIMIT';end if;
 insert into social_request_log(owner_id,kind)values(u,'friend');
 insert into friend_pairs values(least(u,p_target),greatest(u,p_target),u,'pending',now(),now()) on conflict(a,b) do update set sender=u,state='pending',updated_at=now();return 'outgoing';
 elsif p_action in ('accept','decline') and r.state='pending' and r.sender<>u then update friend_pairs set state=case p_action when 'accept' then 'accepted' else 'declined' end,updated_at=now() where a=r.a and b=r.b;
 elsif p_action='cancel' and r.state='pending' and r.sender=u or p_action='remove' and r.state='accepted' then update friend_pairs set state='cancelled',updated_at=now() where a=r.a and b=r.b;
 else raise exception 'REQUEST_CHANGED';end if;
 return case p_action when 'accept' then 'accepted' else 'none' end;
end$$;
create function public.friend_list(p_search text default '',p_offset integer default 0) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$declare u uuid:=social_uid();begin
 if length(p_search)>0 and length(trim(p_search))<3 then raise exception 'SEARCH_MINIMUM';end if;
 return coalesce((select jsonb_agg(to_jsonb(x)) from (select p.id,p.username,p.avatar_path,case when r.state='accepted' then 'accepted' when r.state='pending' and r.sender=u then 'outgoing' when r.state='pending' then 'incoming' else 'none' end relation
 from profiles p left join friend_pairs r on r.a=least(u,p.id) and r.b=greatest(u,p.id)
 where p.id<>u and not exists(select 1 from social_blocks where(owner_id=u and target_id=p.id)or(owner_id=p.id and target_id=u))
 and (case when p_search='' then r.state in ('accepted','pending') else left(lower(p.username::text),length(trim(p_search)))=lower(trim(p_search)) end)
 order by case when r.state='pending' and r.sender<>u then 0 else 1 end,p.username limit 25 offset greatest(0,least(p_offset,10000)))x),'[]');end$$;
-- Private deterministic sporting facts, including machines. Nothing here makes them publicly comparable.
create table public.social_facts(owner_id uuid references public.profiles(id) on delete cascade,session_id text,exercise_id text,set_id text,identity_key text,label text,identity jsonb,started_at timestamptz,ended_at timestamptz,performed_at timestamptz,weight numeric,reps integer,tonnage numeric,first_received_at timestamptz not null default clock_timestamp(),active boolean not null default true,revision text,primary key(owner_id,session_id,exercise_id,set_id));
create index social_facts_owner_time on public.social_facts(owner_id,performed_at) where active;
create table public.goal_challenges(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id),target_id uuid references public.profiles(id),metric text not null check(metric in ('sessions','work_sets','tonnage_kg','repetitions_at_weight','weight_at_min_repetitions','exercise_tonnage_in_session')),mode text not null check(mode in ('each','together','personal')),quantity numeric not null check(quantity>0),days integer not null check(days in (7,14,30)),timezone text not null default 'Europe/Paris',state text not null default 'pending' check(state in ('pending','active','declined','cancelled')),created_at timestamptz not null default now(),started_at timestamptz,deadline timestamptz,baseline jsonb,rule_version integer not null default 1);
create table public.goal_abandonments(goal_id uuid references public.goal_challenges(id),owner_id uuid references public.profiles(id),primary key(goal_id,owner_id));
create table public.badge_definitions(id text primary key,definition jsonb not null);
create table public.badge_occurrences(owner_id uuid references public.profiles(id) on delete cascade,badge_id text references public.badge_definitions(id),occurrence_key text,rule_version integer not null default 1,earned_at date not null,primary key(owner_id,badge_id,occurrence_key,rule_version));
create table public.featured_badges(owner_id uuid references public.profiles(id) on delete cascade,badge_id text references public.badge_definitions(id),slot integer check(slot between 1 and 3),primary key(owner_id,slot),unique(owner_id,badge_id));
create table public.badge_revisions(owner_id uuid,changed_at timestamptz not null default now(),previous_count integer,new_count integer);
-- Lock down every new table before granting only explicit RPCs.
do $$declare t text;begin foreach t in array array['social_settings','friend_pairs','social_blocks','social_request_log','social_facts','goal_challenges','goal_abandonments','badge_definitions','badge_occurrences','featured_badges','badge_revisions']loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);end loop;end$$;
