alter table public.social_facts add column order_reliable boolean not null default false;
alter table public.social_facts add column changed_at timestamptz not null default clock_timestamp();
create function public.social_project(p_owner uuid,p_payload jsonb) returns void language plpgsql security definer set search_path=public,pg_temp as $$
declare s jsonb;e jsonb;st jsonb;piece jsonb;ident jsonb;dt timestamptz;en timestamptz;at_time timestamptz;factor numeric;v numeric;w numeric;r numeric;sk text;ek text;sid text;rev text;ton numeric;old_count integer;begin
 update social_facts set active=false where owner_id=p_owner;
 for s in select value from(select distinct on(value->>'id')value,ord from jsonb_array_elements(case when jsonb_typeof(p_payload->'sessions')='array' then p_payload->'sessions' else '[]'::jsonb end)with ordinality a(value,ord)order by value->>'id',ord desc)x loop
 begin dt:=(s->>'date')::timestamptz;en:=(s->>'endedAt')::timestamptz;exception when others then continue;end;
 if dt is null or en is null or en<dt or en>clock_timestamp() or s->>'id' is null or s->>'id'=p_payload->'active'->>'id' then continue;end if;
 sid:=s->>'id';
 for e in select value from jsonb_array_elements(case when jsonb_typeof(s->'exercises')='array' then s->'exercises' else '[]'::jsonb end) loop
 ek:=coalesce(e->>'instanceId',e->>'id');if ek is null then continue;end if;
 for st in select value from jsonb_array_elements(case when jsonb_typeof(e->'sets')='array' then e->'sets' else '[]'::jsonb end) loop
 if st->>'type'='warmup' or st->>'validated'='false' or coalesce(st->>'status','validated') not in ('validated','completed') or jsonb_typeof(st->'w') is distinct from 'number' or jsonb_typeof(st->'r') is distinct from 'number' or st->>'id' is null then continue;end if;
 w:=(st->>'w')::numeric;r:=(st->>'r')::numeric;if w<0 or w>1000000 or r<1 or r>10000 or r<>trunc(r) then continue;end if;
 at_time:=dt;begin if st->>'recordedAt' is not null then at_time:=(st->>'recordedAt')::timestamptz;end if;exception when others then continue;end;
 if at_time<dt or at_time>en or at_time>clock_timestamp() then continue;end if;
 ident:=coalesce(st->'loadIdentity',e->'loadIdentity',jsonb_build_object('convention',coalesce(e->>'convention',''),'unit','kg','lateralMode','unknown'));
 factor:=null;
 if ident->>'version'='1' and ident->>'source' in ('entry','preset','confirmed') and ident->>'unit' in ('kg','lb') and coalesce(ident->>'convention','')<>'' and ident->>'convention' !~* 'préciser|inconnu|ambigu|valeur indiquée' then
 if ident->>'lateralMode' in ('one-side','alternating-total') or ident->>'lateralMode'='total' and ident->>'convention' !~* 'haltère|par côté' then factor:=1;
 elsif ident->>'lateralMode' in ('simultaneous-pair','both-sides') and ident->>'convention' ~* 'haltère|par côté' then factor:=2;end if;end if;
 ton:=w*r;
 for piece in select value from jsonb_array_elements(case when jsonb_typeof(st->'drops')='array' then st->'drops' else '[]'::jsonb end) loop
 if jsonb_typeof(piece->'w')='number' and jsonb_typeof(piece->'r')='number' and (piece->>'w')::numeric>=0 and (piece->>'r')::numeric>0 and trunc((piece->>'r')::numeric)=(piece->>'r')::numeric and coalesce(piece->>'validated','true')<>'false' then ton:=ton+(piece->>'w')::numeric*(piece->>'r')::numeric;end if;end loop;
 ton:=ton*factor*case when ident->>'unit'='lb' then 0.45359237 else 1 end;
 sk:=st->>'id';rev:=md5(jsonb_build_array(s->>'date',en,e->>'id',ident,w,r,ton,at_time)::text);
 insert into social_facts(owner_id,session_id,exercise_id,set_id,identity_key,label,identity,started_at,ended_at,performed_at,weight,reps,tonnage,revision,order_reliable)
 values(p_owner,sid,ek,sk,case when ident->>'convention' !~* 'préciser|inconnu|ambigu|valeur indiquée' and coalesce(ident->>'convention','')<>'' then md5(jsonb_build_array(e->>'id',ident->>'unit',ident->>'convention',ident->>'lateralMode')::text) else null end,left(coalesce(e->>'name','Exercice'),200),ident,dt,en,at_time,w,r::integer,ton,rev,length(s->>'date')>10)
 on conflict(owner_id,session_id,exercise_id,set_id) do update set identity_key=excluded.identity_key,label=excluded.label,identity=excluded.identity,started_at=excluded.started_at,ended_at=excluded.ended_at,performed_at=excluded.performed_at,weight=excluded.weight,reps=excluded.reps,tonnage=excluded.tonnage,active=true,order_reliable=excluded.order_reliable,changed_at=case when social_facts.revision<>excluded.revision then clock_timestamp() else social_facts.changed_at end,revision=excluded.revision;
 end loop;end loop;end loop;
end$$;
create function public.social_timezone(p_owner uuid) returns text language sql stable security definer set search_path=public,pg_temp as $$select coalesce((select timezone from social_settings where owner_id=p_owner),'Europe/Paris')$$;
create function public.goal_value(p_goal uuid,p_owner uuid) returns numeric language plpgsql stable security definer set search_path=public,pg_temp as $$declare g goal_challenges%rowtype;v numeric;begin
 select * into g from goal_challenges where id=p_goal;
 if g.state<>'active' or p_owner not in (g.owner_id,coalesce(g.target_id,g.owner_id)) then return 0;end if;
 select case g.metric when 'sessions' then count(distinct (started_at at time zone g.timezone)::date) filter(where started_at>=g.started_at and ended_at<g.deadline)::numeric when 'work_sets' then count(*)::numeric when 'tonnage_kg' then coalesce(sum(tonnage),0) when 'repetitions_at_weight' then coalesce(max(reps) filter(where weight=(g.baseline->>'weight')::numeric),0) when 'weight_at_min_repetitions' then coalesce(max(weight) filter(where reps>=(g.baseline->>'reps')::integer),0) else 0 end into v
 from social_facts where owner_id=p_owner and active and performed_at>=g.started_at and performed_at<g.deadline and first_received_at<=g.deadline+interval '48 hours' and changed_at<=g.deadline+interval '48 hours' and (g.mode<>'personal' or identity_key=g.baseline->>'identityKey') and (performed_at<>started_at or started_at>=g.started_at and ended_at<g.deadline);
 if g.metric='exercise_tonnage_in_session' then select coalesce(max(t),0) into v from(select sum(tonnage)t from social_facts where owner_id=p_owner and active and identity_key=g.baseline->>'identityKey' and started_at>=g.started_at and ended_at<g.deadline and first_received_at<=g.deadline+interval '48 hours' and changed_at<=g.deadline+interval '48 hours' group by session_id having count(*)=count(tonnage))x;end if;
 return coalesce(v,0);end$$;
create function public.goal_won(p_goal uuid,p_owner uuid) returns boolean language plpgsql stable security definer set search_path=public,pg_temp as $$declare g goal_challenges%rowtype;begin select * into g from goal_challenges where id=p_goal;
 if g.state<>'active' or g.deadline+interval '48 hours'>now() or exists(select 1 from goal_abandonments where goal_id=g.id and owner_id=p_owner) then return false;end if;
 if g.mode='personal' and not exists(select 1 from social_facts where owner_id=g.owner_id and active and revision=g.baseline->>'revision' and session_id=g.baseline->>'sessionId' and set_id=g.baseline->>'setId')then return false;end if;
 if g.mode='together' then return not exists(select 1 from goal_abandonments where goal_id=g.id) and goal_value(g.id,g.owner_id)>0 and goal_value(g.id,g.target_id)>0 and goal_value(g.id,g.owner_id)+goal_value(g.id,g.target_id)>=g.quantity;end if;
 return goal_value(g.id,p_owner)>=g.quantity;end$$;
create function public.social_metrics(p_owner uuid) returns table(day date,sessions numeric,work_sets numeric,tonnage_kg numeric,pr_events numeric,pr_exercise_identities numeric,active_weeks numeric,active_week_streak numeric,personal_challenges_completed numeric,shared_challenges_completed numeric) language sql stable security definer set search_path=public,pg_temp as $$
with facts as(select *, (started_at at time zone social_timezone(p_owner))::date d from social_facts where owner_id=p_owner and active),
 days as(select d,count(distinct session_id) real_sessions,count(*) sets,sum(coalesce(tonnage,0)) ton from facts group by d),
 exercise_sessions as(select identity_key,session_id,min(started_at) started,max(ended_at) ended,max(weight) w,sum(tonnage) ton,count(*)=count(tonnage) complete from facts where identity_key is not null and order_reliable group by identity_key,session_id),
 prs as(select x.* from exercise_sessions x where exists(select 1 from exercise_sessions old where old.identity_key=x.identity_key and old.started<x.started and (old.started at time zone social_timezone(p_owner))::date<>(x.started at time zone social_timezone(p_owner))::date) and not exists(select 1 from exercise_sessions other where other.identity_key=x.identity_key and other.session_id<>x.session_id and other.started=x.started) and
 (x.w>(select max(old.w) from exercise_sessions old where old.identity_key=x.identity_key and old.started<x.started) or x.complete and x.ton>(select max(old.ton) from exercise_sessions old where old.identity_key=x.identity_key and old.started<x.started and old.complete) or exists(select 1 from facts f where f.identity_key=x.identity_key and f.session_id=x.session_id and f.reps>(select max(o.reps) from facts o where o.identity_key=f.identity_key and o.weight=f.weight and o.started_at<x.started)))),
 weeks as(select distinct date_trunc('week',d::timestamp)::date w from days),islands as(select w,w-7*row_number()over(order by w)::integer grp from weeks),runs as(select w,row_number()over(partition by grp order by w)run from islands),
 credits as(select g.*,case when mode='personal' then owner_id::text else least(owner_id,target_id)::text||greatest(owner_id,target_id)::text end pair,(deadline at time zone timezone)::date finish from goal_challenges g where p_owner in (owner_id,coalesce(target_id,owner_id)) and goal_won(g.id,p_owner)),
 dates as(select d from days union select finish from credits)
 select d,case when exists(select 1 from days where days.d=dates.d)then 1 else 0 end::numeric,coalesce((select sets from days where days.d=dates.d),0)::numeric,coalesce((select ton from days where days.d=dates.d),0),
 (select count(*) from prs where (started at time zone social_timezone(p_owner))::date=dates.d)::numeric,
 (select count(distinct identity_key) from prs where (started at time zone social_timezone(p_owner))::date<=dates.d)::numeric,
 (select count(*) from weeks where w<=dates.d)::numeric,
 coalesce((select max(run) from runs where w<=dates.d),0)::numeric,
 (select count(distinct finish) from credits where mode='personal' and finish=dates.d)::numeric,
 (select count(distinct pair) from credits where mode<>'personal' and finish=dates.d)::numeric from dates order by d
$$;
create function public.social_refresh_badges(p_owner uuid) returns void language plpgsql security definer set search_path=public,pg_temp as $$declare before_count integer;begin
 select count(*) into before_count from badge_occurrences where owner_id=p_owner;
 delete from badge_occurrences where owner_id=p_owner;
 insert into badge_occurrences(owner_id,badge_id,occurrence_key,earned_at)
 with daily as(select * from social_metrics(p_owner)),expanded as(select d.id,d.definition,m.day,case d.definition->>'metric' when 'sessions' then m.sessions when 'work_sets' then m.work_sets when 'tonnage_kg' then m.tonnage_kg when 'pr_events' then m.pr_events when 'pr_exercise_identities' then m.pr_exercise_identities when 'active_weeks' then m.active_weeks when 'active_week_streak' then m.active_week_streak when 'personal_challenges_completed' then m.personal_challenges_completed else m.shared_challenges_completed end value from badge_definitions d cross join daily m),running as(select *,case when definition->>'window'='calendar_week' then sum(value)over(partition by id,date_trunc('week',day::timestamp) order by day) when definition->>'metric' in ('pr_exercise_identities','active_weeks','active_week_streak') then value else sum(value)over(partition by id order by day) end progress from expanded)
 select p_owner,id,case when definition->>'window'='calendar_week' then date_trunc('week',day::timestamp)::date::text else 'lifetime' end,min(day) from running where progress>=(definition->>'threshold')::numeric group by id,definition->>'window',case when definition->>'window'='calendar_week' then date_trunc('week',day::timestamp)::date::text else 'lifetime' end;
 delete from featured_badges f where owner_id=p_owner and not exists(select 1 from badge_occurrences b where b.owner_id=p_owner and b.badge_id=f.badge_id);
 if before_count<>(select count(*) from badge_occurrences where owner_id=p_owner)then insert into badge_revisions values(p_owner,now(),before_count,(select count(*) from badge_occurrences where owner_id=p_owner));end if;
end$$;
create function public.personal_candidates() returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$declare u uuid:=social_uid();begin
 return coalesce((select jsonb_agg(to_jsonb(x))from(select distinct on(identity_key,weight) identity_key as "identityKey",label,identity,weight,reps,(select max(total)from(select sum(x.tonnage)total from social_facts x where x.owner_id=u and x.active and x.identity_key=social_facts.identity_key group by x.session_id having count(*)=count(x.tonnage))v)tonnage,session_id as "sessionId",set_id as "setId",revision from social_facts where owner_id=u and active and identity_key is not null order by identity_key,weight,reps desc,performed_at desc limit 500)x),'[]');end$$;
create function public.goal_create(p_target uuid,p_metric text,p_quantity numeric,p_days integer,p_mode text,p_baseline jsonb default null) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$
declare u uuid:=social_uid();g uuid;baseline jsonb;z text:=social_timezone(u);begin
 perform pg_advisory_xact_lock(hashtextextended(u::text,106));
 if p_days not in (7,14,30) or p_days is null or p_quantity is null or p_quantity<=0 or p_mode is null or p_metric is null then raise exception 'INVALID_GOAL';end if;
 if (select count(*) from goal_challenges where (owner_id=u or target_id=u) and(state='pending' and created_at>now()-interval '7 days' or state='active' and deadline>now()))>=10 then raise exception 'ACTIVE_GOAL_LIMIT';end if;
 if p_mode='personal' then
 if p_target is not null or p_metric not in ('repetitions_at_weight','weight_at_min_repetitions','exercise_tonnage_in_session') then raise exception 'INVALID_GOAL';end if;
 select jsonb_build_object('identityKey',identity_key,'label',label,'identity',identity,'weight',weight,'reps',reps,'sessionId',session_id,'setId',set_id,'revision',revision) into baseline from social_facts where owner_id=u and active and identity_key is not null and session_id=p_baseline->>'sessionId' and set_id=p_baseline->>'setId' and revision=p_baseline->>'revision';
 if baseline is null then raise exception 'REFERENCE_CHANGED';end if;
 if p_metric='repetitions_at_weight' and (p_quantity<= (select max(reps) from social_facts where owner_id=u and active and identity_key=baseline->>'identityKey' and weight=(baseline->>'weight')::numeric) or p_quantity>10000 or trunc(p_quantity)<>p_quantity) then raise exception 'INVALID_TARGET';end if;
 if p_metric='weight_at_min_repetitions' and (p_quantity<=(select max(weight)from social_facts where owner_id=u and active and identity_key=baseline->>'identityKey' and reps>=(baseline->>'reps')::integer) or p_quantity>1000000)then raise exception 'INVALID_TARGET';end if;
 if p_metric='exercise_tonnage_in_session' then
 baseline:=baseline||jsonb_build_object('tonnage',(select max(t) from(select sum(tonnage)t from social_facts where owner_id=u and active and identity_key=baseline->>'identityKey' group by session_id having count(*)=count(tonnage))v));
 if baseline->>'tonnage' is null or p_quantity<=(baseline->>'tonnage')::numeric then raise exception 'TONNAGE_UNAVAILABLE';end if;end if;
 elsif p_mode in ('each','together') then
 if p_target is null or not social_friends(u,p_target)then raise exception 'FRIEND_REQUIRED';end if;
 if p_metric not in ('sessions','work_sets','tonnage_kg') or p_metric='sessions' and(p_quantity>30 or trunc(p_quantity)<>p_quantity) or p_metric='work_sets' and(p_quantity>1000 or trunc(p_quantity)<>p_quantity) or p_metric='tonnage_kg' and (p_quantity<1000 or p_quantity>1000000)then raise exception 'INVALID_GOAL';end if;
 select id into g from goal_challenges where owner_id=u and target_id=p_target and metric=p_metric and mode=p_mode and quantity=p_quantity and days=p_days and state='pending' and created_at>now()-interval '7 days';if g is not null then return g;end if;
 else raise exception 'INVALID_GOAL';end if;
 if(select count(*)from social_request_log where owner_id=u and kind='goal' and created_at>now()-interval '1 day')>=20 then raise exception 'INVITATION_LIMIT';end if;
 insert into social_request_log(owner_id,kind)values(u,'goal');
 insert into goal_challenges(owner_id,target_id,metric,mode,quantity,days,timezone,state,started_at,deadline,baseline)
 values(u,p_target,p_metric,p_mode,p_quantity,p_days,z,case when p_mode='personal' then 'active' else 'pending' end,case when p_mode='personal' then now() end,case when p_mode='personal' then ((now() at time zone z)+make_interval(days=>p_days))at time zone z end,baseline) returning id into g;return g;
end$$;
create function public.goal_action(p_id uuid,p_action text) returns void language plpgsql security definer set search_path=public,pg_temp as $$declare u uuid:=social_uid();g goal_challenges%rowtype;begin
 perform pg_advisory_xact_lock(hashtextextended(u::text,106));
 select * into g from goal_challenges where id=p_id and u in(owner_id,coalesce(target_id,owner_id))for update;
 if not found then raise exception 'GOAL_NOT_FOUND';end if;
 if p_action='abandon' and g.state='active' then insert into goal_abandonments values(g.id,u)on conflict do nothing;return;end if;
 if g.state<>'pending' or g.created_at<=now()-interval '7 days' then raise exception 'INVITATION_CHANGED';end if;
 if p_action='accept' and g.target_id=u then
 if not social_friends(g.owner_id,u)then raise exception 'FRIEND_REQUIRED';end if;
 if(select count(*)from goal_challenges where (owner_id=u or target_id=u) and state='active' and deadline>now())>=10 then raise exception 'ACTIVE_GOAL_LIMIT';end if;
 update goal_challenges set state='active',started_at=now(),deadline=((now()at time zone timezone)+make_interval(days=>days))at time zone timezone where id=p_id;
 elsif p_action='decline' and g.target_id=u then update goal_challenges set state='declined' where id=p_id;
 elsif p_action='cancel' and g.owner_id=u then update goal_challenges set state='cancelled' where id=p_id;
 else raise exception 'FORBIDDEN_ACTION';end if;
end$$;
create function public.goal_list() returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$declare u uuid:=social_uid();begin
 return coalesce((select jsonb_agg(to_jsonb(x))from(select g.id,g.owner_id,g.target_id,g.metric,g.mode,g.quantity,g.days,g.baseline,g.started_at,g.deadline,g.created_at,a.username initiator,b.username target,
 case when g.state='pending' and (g.created_at<=now()-interval '7 days' or not social_friends(g.owner_id,g.target_id))then 'expired' when g.state='active' and g.deadline+interval '48 hours'<=now()then 'completed' when g.state='active' and g.deadline<=now()then 'confirming' else g.state end status,
 goal_value(g.id,g.owner_id)owner_value,goal_value(g.id,g.target_id)target_value,goal_won(g.id,u) won,
 exists(select 1 from goal_abandonments where goal_id=g.id and owner_id=u)abandoned,
 g.mode='personal' and not exists(select 1 from social_facts where owner_id=u and active and revision=g.baseline->>'revision' and session_id=g.baseline->>'sessionId' and set_id=g.baseline->>'setId')reference_invalid
 from goal_challenges g join profiles a on a.id=g.owner_id left join profiles b on b.id=g.target_id where u in(g.owner_id,coalesce(g.target_id,g.owner_id))order by g.created_at desc limit 100)x),'[]');end$$;
create function public.badge_feature(p_badge text,p_slot integer) returns void language plpgsql security definer set search_path=public,pg_temp as $$declare u uuid:=social_uid();begin
 perform pg_advisory_xact_lock(hashtextextended(u::text,107));perform social_refresh_badges(u);
 if p_slot is null or p_slot not between 1 and 3 then raise exception 'INVALID_SLOT';end if;
 if p_badge is null then delete from featured_badges where owner_id=u and slot=p_slot;return;end if;
 if not exists(select 1 from badge_occurrences where owner_id=u and badge_id=p_badge)then raise exception 'BADGE_NOT_EARNED';end if;
 delete from featured_badges where owner_id=u and badge_id=p_badge;
 insert into featured_badges values(u,p_badge,p_slot)on conflict(owner_id,slot)do update set badge_id=excluded.badge_id;end$$;
create function public.social_current_streak(p_owner uuid)returns integer language sql stable security definer set search_path=public,pg_temp as $$with weeks as(select distinct date_trunc('week',started_at at time zone social_timezone(p_owner))::date w from social_facts where owner_id=p_owner and active),latest as(select max(w)w from weeks),ordered as(select w,row_number()over(order by w desc)n from weeks)select case when (select w from latest)<date_trunc('week',now()at time zone social_timezone(p_owner))::date-7 then 0 else (select count(*)::integer from ordered where w=(select w from latest)-7*(n::integer-1))end$$;
revoke all on function public.social_current_streak(uuid)from public,anon,authenticated;
create function public.social_profile(p_username text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare u uuid;p jsonb;begin
 select id into u from profiles where username=p_username::citext;if u is null then return null;end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text,107));perform social_refresh_badges(u);
 select jsonb_build_object('id',u,'badges',coalesce((select jsonb_agg(to_jsonb(x))from(select badge_id,min(earned_at)earned_at,count(*)occurrences from badge_occurrences where owner_id=u group by badge_id)x),'[]'::jsonb),'featured',coalesce((select jsonb_agg(badge_id order by slot)from featured_badges where owner_id=u),'[]'::jsonb),
 'currentStreak',social_current_streak(u),'totals',(select jsonb_build_object('sessions',coalesce(sum(sessions),0),'work_sets',coalesce(sum(work_sets),0),'tonnage_kg',coalesce(sum(tonnage_kg),0),'pr_events',coalesce(sum(pr_events),0),'personal_challenges_completed',coalesce(sum(personal_challenges_completed),0),'shared_challenges_completed',coalesce(sum(shared_challenges_completed),0),'pr_exercise_identities',coalesce(max(pr_exercise_identities),0),'active_weeks',coalesce(max(active_weeks),0),'active_week_streak',coalesce(max(active_week_streak),0))from social_metrics(u)),
 'week',(select jsonb_build_object('sessions',coalesce(sum(sessions),0),'work_sets',coalesce(sum(work_sets),0),'tonnage_kg',coalesce(sum(tonnage_kg),0))from social_metrics(u)where day>=date_trunc('week',now()at time zone social_timezone(u))::date),
 'excludedSets',(select count(*)from social_facts where owner_id=u and active and tonnage is null)) into p;return p;end$$;
create function public.community_capabilities() returns jsonb language sql stable as $$select '{"version":1,"friends":true,"goalChallenges":true,"badges":true}'::jsonb$$;
create function public.social_after_sync() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$begin perform social_project(new.owner_id,new.payload);perform social_refresh_badges(new.owner_id);return new;end$$;
create trigger social_projection_updated after insert or update of payload on public.private_documents for each row execute function public.social_after_sync();
create function public.community_activity(p_kind text default 'regularity') returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$declare u uuid:=social_uid();begin
 if p_kind not in ('regularity','challenges')then raise exception 'INVALID_FILTER';end if;
 return coalesce((select jsonb_agg(to_jsonb(x))from(select p.username,coalesce(max(m.active_week_streak),0)best_streak,coalesce(sum(m.personal_challenges_completed+m.shared_challenges_completed)filter(where m.day>=(now()at time zone social_timezone(p.id))::date-30),0)challenge_credits from profiles p left join lateral social_metrics(p.id)m on true where p.id=u or social_friends(u,p.id) group by p.id,p.username order by case when p_kind='regularity' then coalesce(max(m.active_week_streak),0)else coalesce(sum(m.personal_challenges_completed+m.shared_challenges_completed)filter(where m.day>=(now()at time zone social_timezone(p.id))::date-30),0)end desc,p.username limit 50)x),'[]');end$$;
revoke all on function public.community_activity(text) from public;grant execute on function public.community_activity(text)to authenticated;
create or replace function public.community_rankings(p_variant text,p_kind text default 'charge',p_weight numeric default null,p_reps integer default null,p_offset integer default 0,p_limit integer default 25,p_friends boolean default false)
returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare entries jsonb;records jsonb;total bigint;mine bigint;cap integer:=greatest(1,least(coalesce(p_limit,25),50));off integer:=greatest(0,least(coalesce(p_offset,0),100000));
begin
 if p_kind not in ('charge','tonnage','repetitions') or p_kind='repetitions' and (p_weight is null or p_weight<0 or p_weight>1000000) or p_reps is not null and p_reps not between 1 and 10000 then raise exception 'INVALID_FILTER';end if;
 if not exists(select 1 from public.exercise_variants where id=p_variant and equipment in ('barbell','dumbbell','kettlebell')) then return jsonb_build_object('records','{}'::jsonb,'entries','[]'::jsonb,'total',0,'myRank',null,'notComparable',true);end if;
 -- Absolute load/tonnage cards remain independent of the exact-repetitions list filter.
 select coalesce(jsonb_object_agg(k.kind,k.card),'{}'::jsonb) into records from (
  select kinds.kind,(select jsonb_build_object('value',a.value,'reps',a.reps,'ownerId',a.owner_id,'username',p.username,'ties',(select count(*) from public.absolute_bests t where (not p_friends or t.owner_id=auth.uid() or public.social_friends(auth.uid(),t.owner_id)) and t.variant_id=p_variant and t.kind=kinds.kind and t.value=a.value)) from public.absolute_bests a join public.profiles p on p.id=a.owner_id where (not p_friends or a.owner_id=auth.uid() or public.social_friends(auth.uid(),a.owner_id)) and a.variant_id=p_variant and a.kind=kinds.kind order by a.value desc,p.username,a.owner_id limit 1) card from (values('charge'),('tonnage')) kinds(kind)
 ) k;
 with source as (
  select distinct on(owner_id) owner_id,case when p_kind='repetitions' then reps::numeric else weight end value,reps,id,performed_at
  from public.competition_performances where active and (not p_friends or owner_id=auth.uid() or public.social_friends(auth.uid(),owner_id)) and variant_id=p_variant and p_kind in ('charge','repetitions') and (p_kind<>'repetitions' or weight=p_weight) and (p_kind<>'charge' or p_reps is null or reps=p_reps)
  order by owner_id,(case when p_kind='repetitions' then reps::numeric else weight end) desc,reps desc,performed_at,id
 ),tonnages as(
  select owner_id,sum(tonnage) value,null::integer reps,null::uuid id,max(performed_at) performed_at,session_key from public.competition_performances where active and (not p_friends or owner_id=auth.uid() or public.social_friends(auth.uid(),owner_id)) and variant_id=p_variant and p_kind='tonnage' group by owner_id,session_key having count(*)=count(tonnage)
 ),tonnage_best as(select distinct on(owner_id) owner_id,value,reps,id,performed_at from tonnages order by owner_id,value desc,performed_at,session_key),all_source as(select * from source union all select * from tonnage_best),ranked as(select *,rank() over(order by value desc) rank from all_source),page as(
  select r.rank,r.value,r.reps,r.owner_id as "ownerId",r.id as "performanceId",r.performed_at,p.username,p.avatar_path from ranked r join public.profiles p on p.id=r.owner_id order by r.rank,p.username,r.owner_id limit cap offset off
 ) select coalesce((select jsonb_agg(to_jsonb(page)) from page),'[]'::jsonb),(select count(*) from ranked),(select rank from ranked where owner_id=auth.uid()) into entries,total,mine;
 if p_weight is not null then
  with best as(select distinct on(owner_id) owner_id,reps,weight,id from public.competition_performances where active and (not p_friends or owner_id=auth.uid() or public.social_friends(auth.uid(),owner_id)) and variant_id=p_variant and weight=p_weight order by owner_id,reps desc,id),top as(select b.*,p.username from best b join public.profiles p on p.id=b.owner_id order by reps desc,p.username limit 1)
  select records||jsonb_build_object('repetitions',(select jsonb_build_object('value',reps,'reps',reps,'weight',weight,'username',username,'ownerId',owner_id,'ties',(select count(*) from best where reps=top.reps)) from top)) into records;
 end if;
 return jsonb_build_object('records',records,'entries',entries,'total',total,'myRank',mine,'offset',off,'limit',cap,'tonnageCoverage','Séries à convention et latéralité explicites uniquement','declared',true);
end $$;

revoke all on function public.community_rankings(text,text,numeric,integer,integer,integer,boolean)from public;grant execute on function public.community_rankings(text,text,numeric,integer,integer,integer,boolean)to anon,authenticated;
create function public.social_block_pending()returns trigger language plpgsql security definer set search_path=public,pg_temp as $$begin update goal_challenges set state='cancelled' where state='pending' and(owner_id=new.owner_id and target_id=new.target_id or owner_id=new.target_id and target_id=new.owner_id);return new;end$$;
revoke all on function public.social_block_pending()from public,anon,authenticated;
create trigger social_block_pending after insert on public.social_blocks for each row execute function public.social_block_pending();
-- Never export helpers, provenance, or private tables through the client API.
do $$declare f record;begin for f in select p.oid::regprocedure::text signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('social_uid','social_friends','friend_action','friend_list','social_project','social_timezone','goal_value','goal_won','social_metrics','social_refresh_badges','personal_candidates','goal_create','goal_action','goal_list','badge_feature','social_profile','community_capabilities','social_after_sync')loop execute 'revoke all on function '||f.signature||' from public,anon,authenticated';end loop;end$$;
grant execute on function public.friend_action(uuid,text),public.friend_list(text,integer),public.personal_candidates(),public.goal_create(uuid,text,numeric,integer,text,jsonb),public.goal_action(uuid,text),public.goal_list(),public.badge_feature(text,integer) to authenticated;
grant execute on function public.social_profile(text),public.community_capabilities() to anon,authenticated;
-- Backfill only projections, never rewrite documents or user history.
do $$declare d record;begin for d in select owner_id,payload from public.private_documents loop perform social_project(d.owner_id,d.payload);perform social_refresh_badges(d.owner_id);end loop;end$$;
notify pgrst,'reload schema';
commit;
